```typescript
'use server'

import { revalidateTag } from 'next/cache'
import { redirect } from 'next/navigation'
import { db } from '@/lib/db'

export async function createPost(formData: FormData) {
  await db.post.create({
    data: {
      title: formData.get('title') as string,
      content: formData.get('content') as string,
    },
  })

  revalidateTag('posts')
  redirect('/posts')
}
```

`revalidateTag('posts')` from `next/cache` is the function for cache tag invalidation. It marks all entries tagged `'posts'` as stale, so the next request triggers a fresh fetch instead of serving stale content. The `redirect('/posts')` then forces a navigation that will render with the freshly fetched data, guaranteeing the user sees the new post without stale cached output.
